/// <summary>
/// Manager class for DSD (Duales System) related operations.
/// </summary>
public class AVARUMDSDManager
{
}

Method.Source:
/// <summary>
/// Retrieves the default DSD ItemId from the DSD parameters.
/// </summary>
/// <param name="throwIfNotSet">Optional parameter to indicate whether to throw an error if the ItemId is not set. Default is false.</param>
/// <returns>
/// The default <c>ItemId</c> as defined in <see cref="AVARUMDSDParameters"/>.
/// </returns>
static ItemId getDefaultDSDItemId(boolean throwIfNotSet = false)
{
    var itemId = AVARUMDSDParameters::find().ItemId;

    if (!itemId && throwIfNotSet)
    {
        throw Global::error("@AVARUM:DSDParametersNoItemIdDefined");
    }

    return itemId;
}
